(function(E){ const x = E["exam-04"] = E["exam-04"] || {units:{}}; (x.units = x.units || {})["x04-w2"] = {"id":"x04-w2","patterns":["W2-opinion","W2T-education","TR-halfquestion"],"title":{"en":"Writing Task 2","tr":"Writing Task 2","fa":"Writing Task 2 (نوشتن، تکلیف ۲)"},"objective":{"en":"In this lesson you will learn to answer an opinion question that also asks a direct question: give your view on how far you agree, support it, and answer the direct question clearly, in at least 250 words.","tr":"Bu derste doğrudan bir soru da soran bir görüş sorusunu cevaplamayı öğreneceksin: ne ölçüde katıldığına dair görüşünü verecek, destekleyecek ve doğrudan soruyu açıkça cevaplayacaksın, en az 250 kelimeyle.","fa":"در این درس یاد می‌گیری به سؤالی نظری جواب بدهی که یک سؤال مستقیم هم می‌پرسد: بگویی تا چه حد موافقی، از نظرت پشتیبانی کنی و به سؤال مستقیم روشن جواب بدهی، در دست‌کم ۲۵۰ کلمه."},"sessions":[["explain"],["writing"],["exit"]],"explain":{"title":{"en":"Writing Task 2: an opinion and a direct question","tr":"Writing Task 2: bir görüş ve doğrudan bir soru","fa":"Writing Task 2: نظر و یک سؤال مستقیم"},"objective":{"en":"In this lesson you will learn to answer an opinion question that also asks a direct question: give your view on how far you agree, support it, and answer the direct question clearly, in at least 250 words.","tr":"Bu derste doğrudan bir soru da soran bir görüş sorusunu cevaplamayı öğreneceksin: ne ölçüde katıldığına dair görüşünü verecek, destekleyecek ve doğrudan soruyu açıkça cevaplayacaksın, en az 250 kelimeyle.","fa":"در این درس یاد می‌گیری به سؤالی نظری جواب بدهی که یک سؤال مستقیم هم می‌پرسد: بگویی تا چه حد موافقی، از نظرت پشتیبانی کنی و به سؤال مستقیم روشن جواب بدهی، در دست‌کم ۲۵۰ کلمه."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"250+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"40 min","tr":"40 dk","fa":"۴۰ دقیقه"}},{"label":{"en":"Parts to answer","tr":"Cevaplanacak kısım","fa":"بخش‌های سؤال"},"value":"2"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: when should school start?","tr":"Bu sınav: okul ne zaman başlamalı?","fa":"این آزمون: مدرسه از کی باید شروع شود؟"},"intro":{"en":"\"To what extent do you agree or disagree?\" is the most common Task 2 question type, and education is one of its most common themes. Sometimes a second, direct question is added, and it must be answered too.","tr":"\"Ne ölçüde katılıyorsun?\" en yaygın Task 2 soru türüdür ve eğitim en yaygın konularındandır. Bazen ikinci, doğrudan bir soru eklenir; onun da cevaplanması gerekir.","fa":"«تا چه حد موافق یا مخالفی؟» رایج‌ترین نوع سؤال Task 2 است و آموزش یکی از رایج‌ترین موضوع‌هایش. گاهی یک سؤال دوم و مستقیم هم اضافه می‌شود که باید به آن هم جواب داد."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-w2-ctx","exam":true,"patterns":["W2-opinion","W2T-education"],"often":{"pattern":"W2-opinion","n":20,"of":76,"label":{"en":"Comes up often in the real exam: 20 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 20’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۰ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}},"title":{"en":"Lessons or play for five-year-olds?","tr":"Beş yaşındakiler için ders mi, oyun mu?","fa":"درس یا بازی برای بچه‌های پنج‌ساله؟"},"asks":{"en":"An \"agree or disagree\" essay with an extra direct question: should formal reading and maths lessons start at five, instead of learning through play, and at what age should they begin? You must answer both parts.","tr":"Ek bir doğrudan soru içeren \"katılıyor musun\" türünde bir deneme: resmî okuma ve matematik dersleri oyunla öğrenme yerine beş yaşında mı başlamalı ve hangi yaşta başlamalı? İki kısmı da cevaplamalısın.","fa":"یک مقاله‌ی «موافقی یا مخالف» با یک سؤال مستقیم اضافه: آیا درس رسمی خواندن و ریاضی باید به جای یادگیری با بازی از پنج‌سالگی شروع شود و از چه سنی باید شروع شود؟ باید به هر دو بخش جواب بدهی."},"fields":["Your position","Reasons","The other side","Your answer to the direct question"],"words":[{"a":"formal lessons","b":"structured teaching at desks","tr":"resmî dersler","fa":"درس‌های رسمی"},{"a":"learning through play","b":"learning by playing games and exploring","tr":"oyunla öğrenme","fa":"یادگیری از راه بازی"},{"a":"a head start","b":"an early advantage","tr":"erken avantaj","fa":"یک قدم جلوتر بودن"},{"a":"literacy","b":"reading and writing","tr":"okuryazarlık","fa":"سواد خواندن و نوشتن"},{"a":"numeracy","b":"basic maths","tr":"temel matematik becerisi","fa":"مهارت پایه‌ی ریاضی"},{"a":"concentrate","b":"pay attention for a long time","tr":"konsantre olmak","fa":"تمرکز کردن"},{"a":"social skills","b":"getting on with others","tr":"sosyal beceriler","fa":"مهارت‌های اجتماعی"},{"a":"pressure","b":"stress to perform","tr":"baskı","fa":"فشار"},{"a":"curiosity","b":"wanting to find out","tr":"merak","fa":"کنجکاوی"},{"a":"in the long term","b":"years later","tr":"uzun vadede","fa":"در درازمدت"},{"a":"I partly agree","b":"I agree to some extent","tr":"kısmen katılıyorum","fa":"تا حدی موافقم"},{"a":"by the age of","b":"no later than","tr":"... yaşına kadar","fa":"تا سنِ"}],"traps":[{"en":"Half the question. This question has two parts: how far you agree, and the age you suggest. An essay that never names an age has answered only half.","tr":"Sorunun yarısı. Bu soru iki kısımlıdır: ne ölçüde katıldığın ve önerdiğin yaş. Hiç yaş söylemeyen bir deneme sorunun yalnızca yarısını cevaplamış olur.","fa":"نصفِ سؤال. این سؤال دو بخش دارد: تا چه حد موافقی و چه سنی را پیشنهاد می‌کنی. مقاله‌ای که هیچ سنی نمی‌گوید فقط به نصف سؤال جواب داده."},{"en":"A position that changes. If you \"partly agree\", say so in the introduction and keep the same view to the end.","tr":"Değişen bir tutum. \"Kısmen katılıyorsan\" bunu girişte söyle ve sonuna kadar aynı görüşte kal.","fa":"موضعی که عوض می‌شود. اگر «تا حدی موافقی»، این را در مقدمه بگو و تا آخر همان نظر را نگه دار."}],"example":{"text":"Question: Some people think that children should learn a foreign language from the age of four. To what extent do you agree or disagree? Which language should they learn?","item":"Which introduction answers both parts?","answer":"I agree that an early start helps, and I believe the best choice is the language most used in the child’s region for work and travel.","why":{"en":"It gives a position and answers the direct question at once.","tr":"Bir tutum veriyor ve doğrudan soruyu hemen cevaplıyor.","fa":"یک موضع می‌دهد و فوراً به سؤال مستقیم هم جواب می‌دهد."}}},{"id":"W2T-education","ctx":["W2-opinion","W2-discuss","W2T-education"],"title":{"en":"Education, children and young people","tr":"Eğitim, çocuklar ve gençler","fa":"آموزش، کودکان و جوانان"},"asks":{"en":"Questions about school and growing up: school subjects, holidays, play, independence, smartphones, rules for teenagers and choosing what to study.","tr":"Okul ve büyüme üzerine sorular: dersler, tatiller, oyun, bağımsızlık, akıllı telefonlar, gençler için kurallar ve ne okunacağını seçmek.","fa":"سؤال‌هایی درباره‌ی مدرسه و بزرگ شدن: درس‌ها، تعطیلات، بازی، استقلال، گوشی هوشمند، قانون برای نوجوان‌ها و انتخاب رشته."},"fields":["Should schools teach practical skills instead of academic subjects?","Should children be allowed phones at school?","Study what you enjoy, or what leads to a job?","Should teenagers have a curfew?","Do children today have less freedom than in the past?"],"words":[{"a":"school subjects","b":"the curriculum","tr":"müfredat","fa":"برنامه‌ی درسی"},{"a":"students","b":"learners / pupils","tr":"öğrenciler","fa":"دانش‌آموزان"},{"a":"useful skills","b":"practical skills such as cooking or managing money","tr":"pratik beceriler","fa":"مهارت‌های عملی"},{"a":"book learning","b":"academic / theoretical subjects","tr":"akademik dersler","fa":"درس‌های نظری"},{"a":"doing things alone","b":"independence / self-reliance","tr":"bağımsızlık","fa":"استقلال"},{"a":"time on phones","b":"screen time","tr":"ekran süresi","fa":"زمان استفاده از صفحه‌نمایش"},{"a":"focus","b":"concentration / attention span","tr":"dikkat süresi","fa":"تمرکز"},{"a":"rules","b":"discipline / boundaries","tr":"disiplin, sınırlar","fa":"انضباط و حد و مرز"},{"a":"job chances","b":"career prospects","tr":"kariyer olanakları","fa":"چشم‌انداز شغلی"},{"a":"mums and dads","b":"parents / families","tr":"ebeveynler","fa":"والدین"},{"a":"grow","b":"develop / build","tr":"geliştirmek","fa":"پرورش دادن"},{"a":"exam pressure","b":"the stress of tests","tr":"sınav baskısı","fa":"فشار امتحان"}],"traps":[{"en":"\"Discuss both views\": one paragraph for each view, then your own opinion. Do not skip a view.","tr":"\"İki görüşü tartış\": her görüş için bir paragraf, sonra kendi görüşün. Bir görüşü atlama.","fa":"«هر دو دیدگاه را بررسی کن»: برای هر دیدگاه یک پاراگراف، بعد نظر خودت. هیچ دیدگاهی را جا نینداز."},{"en":"Examples must be specific: \"in Finland children start school at seven\" is stronger than \"in some countries\".","tr":"Örnekler somut olmalı: \"Finlandiya’da çocuklar okula yedi yaşında başlar\", \"bazı ülkelerde\"den daha güçlüdür.","fa":"مثال باید مشخص باشد: «در فنلاند بچه‌ها در هفت‌سالگی مدرسه می‌روند» از «در بعضی کشورها» قوی‌تر است."}],"example":{"text":"Question: Some people think schools should teach children how to manage money. Others think this is the job of parents. Discuss both views and give your opinion.","item":"Write a thesis sentence.","answer":"While parents play an important role, I believe that schools should teach basic money skills, because not every family has the knowledge to do so.","why":{"en":"It refers to both views and states one opinion with a reason.","tr":"İki görüşe de değiniyor ve gerekçesiyle tek bir görüş bildiriyor.","fa":"به هر دو دیدگاه اشاره می‌کند و یک نظر را با دلیل می‌گوید."}},"ideas":["+ Practical skills prepare students for adult life.","- Academic subjects train thinking and open more careers.","+ Phones can be learning tools when teachers set clear rules.","- Phones distract students and reduce face-to-face contact.","+ Studying what you enjoy keeps motivation high.","- Job-focused subjects lower the risk of unemployment."],"general":true,"patterns":["W2-opinion","W2-discuss","W2T-education"],"often":{"pattern":"W2T-education","n":10,"of":76,"label":{"en":"Comes up often in the real exam: 10 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 10’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۱۰ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Forty minutes, two answers","tr":"Kırk dakika, iki cevap","fa":"چهل دقیقه، دو جواب"},"body":{"en":"Write at least 250 words in about 40 minutes. Use four paragraphs: an introduction with your position and your answer to the direct question, two body paragraphs with reasons and examples, and a conclusion that repeats both answers.","tr":"Yaklaşık 40 dakikada en az 250 kelime yaz. Dört paragraf kullan: tutumunu ve doğrudan soruya cevabını veren bir giriş, neden ve örnekler içeren iki gövde paragrafı ve iki cevabı tekrarlayan bir sonuç.","fa":"در حدود ۴۰ دقیقه دست‌کم ۲۵۰ کلمه بنویس. چهار پاراگراف: مقدمه‌ای با موضعت و جوابت به سؤال مستقیم، دو پاراگراف بدنه با دلیل و مثال و نتیجه‌ای که هر دو جواب را تکرار می‌کند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Find every question mark","tr":"Her soru işaretini bul","fa":"همه‌ی علامت‌های سؤال را پیدا کن"},"steps":[{"en":"Underline every question in the task: here there are two.","tr":"Görevdeki her sorunun altını çiz: burada iki tane var.","fa":"زیر همه‌ی سؤال‌های تکلیف خط بکش: این‌جا دو تاست."},{"en":"Decide your position (agree, disagree or partly agree) and a clear answer to the direct question.","tr":"Tutumuna (katılıyorum, katılmıyorum ya da kısmen katılıyorum) ve doğrudan soruya net bir cevaba karar ver.","fa":"موضعت (موافق، مخالف یا تا حدی موافق) و یک جواب روشن به سؤال مستقیم را مشخص کن."},{"en":"Give each body paragraph one main reason, explained and supported with an example.","tr":"Her gövde paragrafına açıklanmış ve bir örnekle desteklenmiş tek bir ana neden ver.","fa":"به هر پاراگراف بدنه یک دلیل اصلی بده که توضیح داده شده و با مثال پشتیبانی شده."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Showing how far you agree","tr":"Ne ölçüde katıldığını göstermek","fa":"نشان دادن میزان موافقت"},"table":{"headers":{"en":["How far","Phrase"],"tr":["Ne ölçüde","İfade"],"fa":["چقدر","عبارت"]},"rows":[["completely","I strongly agree that..."],["partly","I agree to some extent, but..."],["not at all","I firmly disagree with the idea that..."],["the direct question","In my view, the best age would be..."],["concluding","For these reasons, I believe..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"An introduction, step by step","tr":"Bir giriş, adım adım","fa":"یک مقدمه، قدم به قدم"},"instruction":"Question: Some people think all teenagers should do voluntary work. To what extent do you agree or disagree? How many hours a week would be reasonable?","item":"Write the last sentence of the introduction.","answer":"I agree to a large extent, and I believe that two hours a week would be enough to help the community without harming schoolwork.","walk":[{"en":"Give your position: \"I agree to a large extent\".","tr":"Tutumunu ver: \"I agree to a large extent\".","fa":"موضعت را بگو: «I agree to a large extent»."},{"en":"Answer the direct question with a number: two hours a week.","tr":"Doğrudan soruyu bir sayıyla cevapla: haftada iki saat.","fa":"به سؤال مستقیم با یک عدد جواب بده: هفته‌ای دو ساعت."},{"en":"Add a short reason, which the body paragraphs will develop.","tr":"Gövde paragraflarının geliştireceği kısa bir neden ekle.","fa":"یک دلیل کوتاه اضافه کن که پاراگراف‌های بدنه بازش می‌کنند."}]},"quick":{"prompt":"A task asks \"To what extent do you agree or disagree? At what age should children start school?\" An essay argues well against early lessons but never suggests an age. What is missing?","options":["an example","an answer to the second question","a conclusion"],"correct":1,"why":{"en":"There are two questions; the second has not been answered.","tr":"İki soru var; ikincisi cevaplanmamış.","fa":"دو سؤال هست؛ به دومی جواب داده نشده."}},"remember":{"en":"Answer every question in the task: your position, and the direct question, in the introduction and again at the end.","tr":"Görevdeki her soruyu cevapla: tutumun ve doğrudan soru, girişte ve sonda yeniden.","fa":"به همه‌ی سؤال‌های تکلیف جواب بده: موضعت و سؤال مستقیم، در مقدمه و دوباره در آخر."},"type":"explain","id":"c-x04-w2-e","course":"ielts-exams","exam":"exam-04","unit":"x04-w2"},"writing":{"taskKind":"exam","title":{"en":"Formal lessons or play at five?","tr":"Beş yaşında resmî ders mi, oyun mu?","fa":"درس رسمی یا بازی در پنج‌سالگی؟"},"task":"task2","reviewLabel":{"en":"Exam 4 · Writing Task 2 (opinion + direct question: formal lessons from age five versus learning through play)"},"timed":40,"minWords":250,"ctx":["W2-opinion","W2T-education"],"prompt":{"en":"You should spend about 40 minutes on this task. Write about the following topic: Some people think that children should start formal lessons in reading and mathematics at the age of five, rather than learning mainly through play. To what extent do you agree or disagree? At what age do you think formal lessons should begin? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.","tr":"Bu göreve yaklaşık 40 dakika ayırmalısın. Şu konu hakkında yaz: Bazı insanlar çocukların, ağırlıklı olarak oyunla öğrenmek yerine beş yaşında okuma ve matematikte resmî derslere başlaması gerektiğini düşünüyor. Ne ölçüde katılıyorsun ya da katılmıyorsun? Sence resmî dersler kaç yaşında başlamalı? Cevabın için nedenler göster ve kendi bilgi ya da deneyiminden ilgili örnekler ekle. En az 250 kelime yaz.","fa":"باید حدود ۴۰ دقیقه برای این تکلیف وقت بگذاری. درباره‌ی موضوع زیر بنویس: بعضی‌ها فکر می‌کنند بچه‌ها باید به جای یادگیری عمدتاً از راه بازی، از پنج‌سالگی درس رسمی خواندن و ریاضی را شروع کنند. تا چه حد موافق یا مخالفی؟ به نظرت درس رسمی از چه سنی باید شروع شود؟ برای جوابت دلیل بیاور و از دانسته‌ها یا تجربه‌ی خودت مثال‌های مرتبط بزن. دست‌کم ۲۵۰ کلمه بنویس."},"model":"In many countries, children begin formal lessons in reading and mathematics at the age of five, while in others they spend their first years at school learning mainly through play. I largely disagree with an early start. Although a little structured teaching can be useful, I believe that formal lessons in these subjects should not begin until children are about seven.\n\nSupporters of early lessons argue that they give children a head start. It is true that some five-year-olds are ready to read, and that children from homes with few books may benefit from extra practice. However, many children of this age find it hard to sit still and concentrate for long periods. When they are pushed too early, they may come to see reading as a source of stress rather than pleasure, and this attitude can last for years.\n\nLearning through play, by contrast, develops the skills that formal learning later depends on. When young children build with blocks, they are learning about shapes and quantities; when they act out stories with friends, they are developing language and social skills. Play also teaches children to solve problems for themselves, a habit they will need throughout their education. In several countries where formal lessons start at six or seven, children quickly catch up with those who started earlier, and they often enjoy school more.\n\nFor these reasons, I believe that the first two years of school should be based mainly on play, with short, enjoyable activities that introduce letters and numbers. Formal lessons in reading and mathematics should begin at around the age of seven, when most children are ready to benefit from them.","moves":[{"label":{"en":"1 Introduction: your position and the age","tr":"1 Giriş: tutumun ve yaş","fa":"۱ مقدمه: موضعت و سن"},"text":"I largely disagree with an early start... formal lessons in these subjects should not begin until children are about seven."},{"label":{"en":"2 The other side, then your reply","tr":"2 Karşı taraf, sonra senin cevabın","fa":"۲ طرف مقابل، بعد جواب تو"},"text":"Supporters of early lessons argue that they give children a head start. It is true that... However, many children of this age find it hard to sit still..."},{"label":{"en":"3 Your main reason, with examples","tr":"3 Ana nedenin, örneklerle","fa":"۳ دلیل اصلی‌ات، با مثال"},"text":"Learning through play, by contrast, develops the skills that formal learning later depends on..."},{"label":{"en":"4 Conclusion: both answers again","tr":"4 Sonuç: iki cevap yeniden","fa":"۴ نتیجه: دوباره هر دو جواب"},"text":"For these reasons... Formal lessons in reading and mathematics should begin at around the age of seven..."}],"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"The question is not really answered; no clear position.","tr":"Soru tam olarak cevaplanmamış; net bir tutum yok.","fa":"در واقع به سؤال جواب داده نشده؛ موضع روشنی نیست."},{"en":"A position, but only part of the question is answered, or ideas are not explained.","tr":"Bir tutum var ama sorunun yalnızca bir kısmı cevaplanmış ya da fikirler açıklanmamış.","fa":"موضعی هست، اما فقط بخشی از سؤال جواب داده شده یا ایده‌ها توضیح داده نشده‌اند."},{"en":"Every part answered, one clear position, main ideas supported.","tr":"Her kısım cevaplanmış, tek ve net bir tutum, ana fikirler desteklenmiş.","fa":"به همه‌ی بخش‌ها جواب داده شده، یک موضع روشن هست و ایده‌های اصلی پشتیبانی شده‌اند."},{"en":"A clear, consistent position; ideas fully explained with relevant examples.","tr":"Net ve tutarlı bir tutum; fikirler yerinde örneklerle tam açıklanmış.","fa":"موضعی روشن و یکدست؛ ایده‌ها با مثال‌های مرتبط کامل توضیح داده شده‌اند."}],"organised":[{"en":"No clear paragraphs.","tr":"Net paragraflar yok.","fa":"پاراگراف‌های روشنی ندارد."},{"en":"Paragraphs, but more than one main idea in each, or forced linking words.","tr":"Paragraflar var ama her birinde birden fazla ana fikir ya da zorlama bağlaçlar.","fa":"پاراگراف دارد، اما در هر کدام بیش از یک ایده‌ی اصلی هست یا کلمه‌های ربط تصنعی‌اند."},{"en":"Introduction, body paragraphs with one idea each, conclusion.","tr":"Giriş, her biri tek fikirli gövde paragrafları, sonuç.","fa":"مقدمه، پاراگراف‌هایی که هر کدام یک ایده دارند، نتیجه."},{"en":"A logical flow from start to end; linking is natural.","tr":"Baştan sona mantıklı bir akış; bağlantılar doğal.","fa":"جریانی منطقی از اول تا آخر؛ ربط‌ها طبیعی‌اند."}],"words":[{"en":"Very basic words; the question is copied.","tr":"Çok temel kelimeler; soru kopyalanmış.","fa":"کلمه‌های خیلی ساده؛ صورت سؤال کپی شده."},{"en":"Topic words repeated; some wrong word choices.","tr":"Konu kelimeleri tekrarlanmış; bazı yanlış kelime seçimleri.","fa":"کلمه‌های موضوع تکرار شده‌اند؛ چند انتخاب کلمه‌ی غلط هست."},{"en":"Topic words used well; the question is said in other words.","tr":"Konu kelimeleri iyi kullanılmış; soru başka sözcüklerle anlatılmış.","fa":"کلمه‌های موضوع خوب به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده."},{"en":"Precise, natural topic words; almost no errors.","tr":"Yerinde, doğal konu kelimeleri; neredeyse hatasız.","fa":"کلمه‌های موضوعِ دقیق و طبیعی؛ تقریباً بی‌غلط."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"rubric":["Covers the task: a clear position, an answer to every part of the question, and ideas supported with reasons and examples.","Organised: an introduction, body paragraphs with one main idea each, and a conclusion.","Words: precise words for the topic; the question is said in other words.","Sentences: a mix of simple and complex sentences, with few errors."],"rubricI18n":{"tr":["Görevi karşılıyor: net bir tutum, sorunun her kısmına cevap ve neden ve örneklerle desteklenmiş fikirler.","Düzenli: giriş, her biri tek ana fikirli gövde paragrafları ve sonuç.","Kelimeler: konu için yerinde kelimeler; soru başka sözcüklerle anlatılmış.","Cümleler: basit ve karmaşık cümlelerin karışımı, az hata."],"fa":["تکلیف را پوشش می‌دهد: موضعی روشن، جواب به همه‌ی بخش‌های سؤال و ایده‌هایی که با دلیل و مثال پشتیبانی شده‌اند.","منظم است: مقدمه، پاراگراف‌هایی که هر کدام یک ایده‌ی اصلی دارند و نتیجه.","کلمه‌ها: کلمه‌های دقیق برای موضوع؛ سؤال با کلمه‌های دیگر بیان شده.","جمله‌ها: ترکیبی از جمله‌های ساده و مرکب، با غلط کم."]},"type":"writing","id":"c-x04-w2-w","course":"ielts-exams","exam":"exam-04","unit":"x04-w2"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"\"Early lessons give children a head start.\" A head start is...","options":["an advantage at the beginning","a difficult beginning","a short break"],"correct":0,"why":{"en":"A head start = an early advantage over others.","tr":"Head start = başkalarına karşı erken bir avantaj.","fa":"head start یعنی امتیازی زودهنگام نسبت به بقیه."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase shows that you agree only partly?","options":["I strongly agree that...","I completely reject...","I agree to some extent, but..."],"correct":2,"why":{"en":"\"To some extent, but\" shows partial agreement.","tr":"\"To some extent, but\" kısmi katılımı gösterir.","fa":"«to some extent, but» نشانه‌ی موافقت نسبی است."}},{"tests":"method","point":2,"prompt":"A task ends with two questions. Where should your answer to the second question first appear?","options":["only in the conclusion","in the introduction","in a separate final paragraph after the conclusion"],"correct":1,"why":{"en":"Give both answers in the introduction, develop them in the body, and repeat them at the end.","tr":"İki cevabı girişte ver, gövdede geliştir ve sonda tekrarla.","fa":"هر دو جواب را در مقدمه بده، در بدنه بازشان کن و در آخر تکرارشان کن."}},{"tests":"trap","point":1,"prompt":"An essay explains the dangers of early lessons but never says at what age lessons should begin. What is the problem?","options":["Part of the question is not answered","It is too long","It disagrees with the question"],"correct":0,"why":{"en":"The direct question asks for an age; leaving it out answers only half the task.","tr":"Doğrudan soru bir yaş istiyor; onu atlamak görevin yalnızca yarısını cevaplamak demek.","fa":"سؤال مستقیم یک سن می‌خواهد؛ جا انداختنش یعنی فقط به نصف تکلیف جواب دادن."}}],"id":"c-x04-w2-x","course":"ielts-exams","exam":"exam-04","unit":"x04-w2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
